Q: How to enable partial text selection in SwiftUI like iOS 26 iMessage A: <p><strong>1.Remove this completely:</strong></p>
<pre class="lang-swift prettyprint-override"><code>final class ChatTextView: UITextView {
    override var intrinsicContentSize: CGSize {
        let size = self.sizeThatFits(
            CGSize(width: self.bounds.width, height: .greatestFiniteMagnitude)
        )
        return CGSize(width: size.width, height: size.height)
    }
}
</code></pre>
<p><strong>2.Replace this line inside</strong></p>
<pre class="lang-swift prettyprint-override"><code>let view = ChatTextView()
</code></pre>
<p><strong>with this:-</strong></p>
<pre class="lang-swift prettyprint-override"><code>let view = UITextView()
</code></pre>
<p><strong>3.Keep the rest of your layout exactly the same:-</strong></p>
<p>Your HStack usage is correct:</p>
<pre class="lang-swift prettyprint-override"><code>HStack {
    Spacer(minLength: 40)

    SelectableTextView(text: message.body, textColor: .white)
        .fixedSize(horizontal: false, vertical: true)
        .frame(
            maxWidth: UIScreen.main.bounds.width * 0.75,
            alignment: .trailing
        )
        .padding(.horizontal)
}
</code></pre>
<p><strong>4.Final Correct <code>SelectableTextView</code></strong></p>
<pre class="lang-swift prettyprint-override"><code>struct SelectableTextView: UIViewRepresentable {
    var text: String
    var textColor: UIColor

    func makeUIView(context: Context) -&gt; UITextView {
        let view = UITextView()

        view.isEditable = false
        view.isSelectable = true
        view.isScrollEnabled = false
        view.backgroundColor = .clear

        view.textContainerInset = .zero
        view.textContainer.lineFragmentPadding = 0

        view.font = UIFont.systemFont(ofSize: 17)
        view.textColor = textColor

        view.setContentHuggingPriority(.required, for: .vertical)
        view.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)

        return view
    }

    func updateUIView(_ uiView: UITextView, context: Context) {
        uiView.text = text
    }
}
</code></pre>
